using System.Data;using System.Data.Common;using AiCare.Application;using AiCare.Domain;using AiCare.Infrastructure;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace AiCare.Api;[ApiController][Authorize(Roles="Administrator,BackOffice,CareManager,CareCoordinator")][Route("api/phase1/reporting-governance")]
public sealed class ReportingDataGovernanceController(CareDbContext db,ITenantContext tenant,ICurrentUserContext user):ControllerBase
{
 [HttpGet]public async Task<IActionResult> Workspace(CancellationToken t)=>Ok(new{metrics=await Rows("select id,key,version,name,description,calculation_key,owner,source_entities,lineage,effective_from,effective_to,status,approved_by from governed_metric_definitions where organization_id=@organization and (@organizationWide or branch_id is null or branch_id=@branch) order by key,version desc",t),reports=await Rows("select id,name,category,description,metric_keys,allowed_roles,field_profile,active from governed_report_catalogue where organization_id=@organization and active=true and (@organizationWide or branch_id is null or branch_id=@branch) order by name",t),schedules=await Rows("select s.id,s.report_catalogue_id,c.name,s.frequency,s.next_run_at,s.enabled,s.last_run_at,s.owner from governed_report_schedules s join governed_report_catalogue c on c.id=s.report_catalogue_id where s.organization_id=@organization and (@organizationWide or s.branch_id=@branch) order by s.next_run_at",t),qualityIssues=await Rows("select id,rule_key,entity_type,entity_id,severity,status,description,owner,detected_at,due_at,resolution,resolved_at from data_quality_issues where organization_id=@organization and (@organizationWide or branch_id=@branch) order by detected_at desc",t)});
 [HttpPost("metrics")][Authorize(Roles="CareManager,Administrator")]public async Task<IActionResult> Metric(MetricRequest r,CancellationToken t){if(string.IsNullOrWhiteSpace(r.Key)||string.IsNullOrWhiteSpace(r.Name)||string.IsNullOrWhiteSpace(r.CalculationKey)||string.IsNullOrWhiteSpace(r.Owner)||string.IsNullOrWhiteSpace(r.Lineage))return BadRequest(new{message="Key, name, calculation, owner and lineage are required."});var next=await Scalar("select coalesce(max(version),0)+1 from governed_metric_definitions where organization_id=@organization and key=@key",c=>Add(c,"key",r.Key),t);var id=Guid.NewGuid();await Exec("insert into governed_metric_definitions(id,organization_id,branch_id,key,version,name,description,calculation_key,owner,source_entities,lineage,effective_from,status) values(@id,@organization,@metricBranch,@key,@version,@name,@description,@calculation,@owner,@sources,@lineage,@effective,'Draft')",c=>{Add(c,"id",id);Add(c,"metricBranch",r.OrganizationWide?null:tenant.BranchId??TenantDefaults.BranchId);Add(c,"key",r.Key);Add(c,"version",next);Add(c,"name",r.Name);Add(c,"description",r.Description);Add(c,"calculation",r.CalculationKey);Add(c,"owner",r.Owner);Add(c,"sources",r.SourceEntities);Add(c,"lineage",r.Lineage);Add(c,"effective",r.EffectiveFrom);},t);Audit("reporting.metric_version_created","MetricDefinition",id);await db.SaveChangesAsync(t);return Created("",new{id,version=next});}
 [HttpPost("metrics/{id:guid}/approve")][Authorize(Roles="CareManager,Administrator")]public async Task<IActionResult> Approve(Guid id,CancellationToken t){var n=await Exec("update governed_metric_definitions set status='Approved',approved_by=@actor,approved_at=now() where id=@id and organization_id=@organization and (@organizationWide or branch_id is null or branch_id=@branch) and status='Draft'",c=>Add(c,"id",id),t);if(n==0)return Conflict(new{message="Only a draft metric can be approved."});Audit("reporting.metric_approved","MetricDefinition",id);await db.SaveChangesAsync(t);return Ok();}
 [HttpPost("catalogue")][Authorize(Roles="CareManager,Administrator")]public async Task<IActionResult> Catalogue(CatalogueRequest r,CancellationToken t){var validRoles=new[]{"Administrator","BackOffice","CareManager","CareCoordinator"};var validProfiles=new[]{"AggregateOnly","AggregateOperational","AggregateFinance"};if(string.IsNullOrWhiteSpace(r.Name)||r.MetricKeys.Count==0||r.AllowedRoles.Count==0||r.AllowedRoles.Any(x=>!validRoles.Contains(x,StringComparer.Ordinal))||!validProfiles.Contains(r.FieldProfile,StringComparer.Ordinal))return BadRequest(new{message="Name, metrics, valid allowed roles, and an aggregate field profile are required."});var approved=await Scalar("select count(*) from governed_metric_definitions where organization_id=@organization and (@organizationWide or branch_id is null or branch_id=@branch) and status='Approved' and key=any(@keys)",c=>Add(c,"keys",r.MetricKeys.ToArray()),t);if(approved<r.MetricKeys.Distinct().Count())return Conflict(new{message="Every report metric must have an approved definition."});var id=Guid.NewGuid();await Exec("insert into governed_report_catalogue(id,organization_id,branch_id,name,category,description,metric_keys,allowed_roles,field_profile,created_by) values(@id,@organization,@catalogueBranch,@name,@category,@description,@keys,@roles,@profile,@actor)",c=>{Add(c,"id",id);Add(c,"catalogueBranch",r.OrganizationWide?null:tenant.BranchId??TenantDefaults.BranchId);Add(c,"name",r.Name);Add(c,"category",r.Category);Add(c,"description",r.Description);Add(c,"keys",r.MetricKeys.ToArray());Add(c,"roles",r.AllowedRoles.ToArray());Add(c,"profile",r.FieldProfile);},t);Audit("reporting.catalogue_created","ReportCatalogue",id);await db.SaveChangesAsync(t);return Created("",new{id});}
 [HttpPost("catalogue/{id:guid}/schedules")][Authorize(Roles="CareManager,Administrator")]public async Task<IActionResult> Schedule(Guid id,ScheduleRequest r,CancellationToken t){if(r.Frequency is not("Daily" or "Weekly" or "Monthly")||r.NextRunAt<=DateTimeOffset.UtcNow)return BadRequest(new{message="Frequency and future next-run time are required."});if(!await Exists("select exists(select 1 from governed_report_catalogue where id=@id and organization_id=@organization and active=true and (@organizationWide or branch_id is null or branch_id=@branch))",c=>Add(c,"id",id),t))return NotFound();var schedule=Guid.NewGuid();await Exec("insert into governed_report_schedules(id,report_catalogue_id,organization_id,branch_id,frequency,next_run_at,owner) values(@schedule,@id,@organization,@branch,@frequency,@next,@owner)",c=>{Add(c,"schedule",schedule);Add(c,"id",id);Add(c,"frequency",r.Frequency);Add(c,"next",r.NextRunAt);Add(c,"owner",r.Owner);},t);Audit("reporting.schedule_created","ReportSchedule",schedule);await db.SaveChangesAsync(t);return Created("",new{id=schedule});}
 [HttpPost("quality/scan")][Authorize(Roles="CareManager,Administrator")]public async Task<IActionResult> Scan(CancellationToken t){var created=0;created+=await Quality("missing-person-dob","ServiceUser","High","Person record has no valid date of birth","select \"Id\" from \"ServiceUsers\" where \"OrganizationId\"=@organization and (\"DateOfBirth\" is null)",t);created+=await Quality("visit-worker-missing","Visit","Critical","Visit references a missing worker","select v.\"Id\" from \"Visits\" v left join \"CareWorkers\" w on w.\"Id\"=v.\"CareWorkerId\" where v.\"OrganizationId\"=@organization and w.\"Id\" is null",t);Audit("reporting.data_quality_scan","DataQualityIssue",null);await db.SaveChangesAsync(t);return Ok(new{created});}
 [HttpPost("quality/{id:guid}/resolve")][Authorize(Roles="CareManager,Administrator")]public async Task<IActionResult> Resolve(Guid id,ResolveQualityRequest r,CancellationToken t){if(string.IsNullOrWhiteSpace(r.Resolution))return BadRequest(new{message="Resolution evidence is required."});var n=await Exec("update data_quality_issues set status='Resolved',resolution=@resolution,resolved_at=now() where id=@id and organization_id=@organization and (@organizationWide or branch_id=@branch) and status in ('Open','Investigating')",c=>{Add(c,"id",id);Add(c,"resolution",r.Resolution);},t);if(n==0)return Conflict(new{message="Only an open quality issue can be resolved."});Audit("reporting.data_quality_resolved","DataQualityIssue",id);await db.SaveChangesAsync(t);return Ok();}
 [HttpGet("report-runs/{id:guid}/governed.csv")]public async Task<IActionResult> Export(Guid id,string reason,CancellationToken t){if(string.IsNullOrWhiteSpace(reason))return BadRequest(new{message="Export reason is required."});var role=user.Role?.ToString()??"Unknown";var row=(await Query("select r.name,r.metrics_json,c.field_profile from report_runs r join governed_report_catalogue c on c.id=r.report_catalogue_id where r.id=@id and r.organization_id=@organization and c.organization_id=@organization and r.branch_id=c.branch_id and (@organizationWide or r.branch_id=@branch) and c.active=true and @role=any(c.allowed_roles)",c=>{Add(c,"id",id);Add(c,"role",role);},r=>new{Name=r.GetString(0),Metrics=r.GetString(1),Profile=r.GetString(2)},t)).FirstOrDefault();if(row is null)return NotFound();var profile=row.Profile;var export=Guid.NewGuid();await Exec("insert into governed_export_events(id,report_run_id,organization_id,branch_id,exported_by,role,field_profile,row_count,reason) values(@export,@id,@organization,@branch,@actor,@role,@profile,1,@reason)",c=>{Add(c,"export",export);Add(c,"id",id);Add(c,"role",role);Add(c,"profile",profile);Add(c,"reason",reason);},t);Audit("reporting.governed_export","ReportRun",id);await db.SaveChangesAsync(t);return File(System.Text.Encoding.UTF8.GetBytes("metric,value\n"+string.Join("\n",System.Text.Json.JsonSerializer.Deserialize<Dictionary<string,decimal>>(row.Metrics)!.Select(x=>$"{x.Key},{x.Value}"))),"text/csv",row.Name+".csv");}
 private async Task<int> Quality(string key,string entity,string severity,string description,string sql,CancellationToken t){var ids=await Query(sql,_=>{},r=>r.GetGuid(0),t);var n=0;foreach(var id in ids){if(await Exists("select exists(select 1 from data_quality_issues where organization_id=@organization and rule_key=@key and entity_id=@entityId and status<>'Resolved')",c=>{Add(c,"key",key);Add(c,"entityId",id);},t))continue;await Exec("insert into data_quality_issues(id,organization_id,branch_id,rule_key,entity_type,entity_id,severity,description,owner,due_at) values(@id,@organization,@branch,@key,@type,@entityId,@severity,@description,'Data steward',now()+interval '7 days')",c=>{Add(c,"id",Guid.NewGuid());Add(c,"key",key);Add(c,"type",entity);Add(c,"entityId",id);Add(c,"severity",severity);Add(c,"description",description);},t);n++;}return n;}private async Task<List<Dictionary<string,object?>>> Rows(string sql,CancellationToken t)=>await Query(sql,_=>{},r=>{var x=new Dictionary<string,object?>();for(var i=0;i<r.FieldCount;i++)x[Camel(r.GetName(i))]=r.IsDBNull(i)?null:r.GetValue(i);return x;},t);private async Task<List<T>> Query<T>(string sql,Action<DbCommand> bind,Func<DbDataReader,T> map,CancellationToken t){await using var c=await Command(sql,t);bind(c);await using var r=await c.ExecuteReaderAsync(t);var l=new List<T>();while(await r.ReadAsync(t))l.Add(map(r));return l;}private async Task<long> Scalar(string sql,Action<DbCommand> bind,CancellationToken t){await using var c=await Command(sql,t);bind(c);return Convert.ToInt64(await c.ExecuteScalarAsync(t));}private async Task<bool> Exists(string sql,Action<DbCommand> bind,CancellationToken t){await using var c=await Command(sql,t);bind(c);return Convert.ToBoolean(await c.ExecuteScalarAsync(t));}private async Task<int> Exec(string sql,Action<DbCommand> bind,CancellationToken t){await using var c=await Command(sql,t);bind(c);return await c.ExecuteNonQueryAsync(t);}private async Task<DbCommand> Command(string sql,CancellationToken t){var cn=db.Database.GetDbConnection();if(cn.State!=ConnectionState.Open)await cn.OpenAsync(t);var c=cn.CreateCommand();c.CommandText=sql;Add(c,"organization",tenant.OrganizationId);Add(c,"branch",tenant.BranchId??TenantDefaults.BranchId);Add(c,"organizationWide",tenant.IsOrganizationWide);Add(c,"actor",user.UserName);return c;}private void Audit(string a,string e,Guid? id)=>db.AuditEvents.Add(new AuditEvent(Guid.NewGuid(),a,user.UserName,e,id,DateTimeOffset.UtcNow,tenant.OrganizationId,tenant.BranchId??TenantDefaults.BranchId));private static void Add(DbCommand c,string n,object? v){if(c.Parameters.Contains(n))return;var p=c.CreateParameter();p.ParameterName=n;p.Value=v??DBNull.Value;c.Parameters.Add(p);}private static string Camel(string v){var p=v.Split('_');return p[0]+string.Concat(p.Skip(1).Select(x=>char.ToUpperInvariant(x[0])+x[1..]));}
}
public sealed record MetricRequest(string Key,string Name,string Description,string CalculationKey,string Owner,string SourceEntities,string Lineage,DateTimeOffset EffectiveFrom,bool OrganizationWide);public sealed record CatalogueRequest(string Name,string Category,string Description,IReadOnlyCollection<string> MetricKeys,IReadOnlyCollection<string> AllowedRoles,string FieldProfile,bool OrganizationWide);public sealed record ScheduleRequest(string Frequency,DateTimeOffset NextRunAt,string Owner);public sealed record ResolveQualityRequest(string Resolution);
